import type { LightMode, MaterialId, ScenePreset } from "@/types";
import { PROJECTS, PROJECT_BY_SLUG } from "./projects";

/**
 * Still renders of the studio's own 3D scenes. These are generated by `scripts/render-stills.mjs`
 * (headless Chromium capturing /render/[id]) and used as fallbacks, thumbnails and editorial imagery.
 * They are 3D renders — not photographs.
 */
export interface RenderSpec {
  id: string;
  out: string;
  preset: ScenePreset;
  camIndex?: number;
  hero?: number;
  mode?: LightMode;
  wall?: MaterialId;
  floor?: MaterialId;
  lettering?: boolean;
}

const gallery = PROJECT_BY_SLUG["quiet-gallery"].preset;
const library = PROJECT_BY_SLUG["walnut-room"].preset;
const suite = PROJECT_BY_SLUG["lumen-suite"].preset;
const dining = PROJECT_BY_SLUG["bronze-table"].preset;
const court = PROJECT_BY_SLUG["stone-court-residence"].preset;
const pavilion = PROJECT_BY_SLUG["sand-pavilion"].preset;

export const RENDERS: RenderSpec[] = [
  ...PROJECTS.flatMap((p) =>
    p.images.map((_, i) => ({ id: `${p.slug}-${i + 1}`, out: `public/images/projects/${p.slug}-${i + 1}.jpg`, preset: p.preset, camIndex: i })),
  ),
  { id: "hero-living-room", out: "public/images/hero/living-room.jpg", preset: gallery, hero: 0.2, lettering: true },
  { id: "hero-dusk", out: "public/images/hero/living-room-dusk.jpg", preset: gallery, hero: 0.2, mode: "dusk", lettering: true },
  { id: "arch-studio-intro", out: "public/images/architecture/studio-intro.jpg", preset: gallery, camIndex: 2 },
  { id: "arch-spatial", out: "public/images/architecture/spatial.jpg", preset: gallery, camIndex: 1, mode: "warm" },
  { id: "arch-philosophy", out: "public/images/architecture/philosophy.jpg", preset: pavilion, camIndex: 0 },
  { id: "arch-story", out: "public/images/architecture/story.jpg", preset: library, camIndex: 2 },
  { id: "arch-services", out: "public/images/architecture/services.jpg", preset: dining, camIndex: 2 },
  { id: "studio-1", out: "public/images/studio/studio-1.jpg", preset: suite, camIndex: 2 },
  { id: "studio-2", out: "public/images/studio/studio-2.jpg", preset: court, camIndex: 1 },
  { id: "editorial-light", out: "public/images/editorial/light.jpg", preset: gallery, camIndex: 0, mode: "warm" },
  { id: "editorial-travertine", out: "public/images/editorial/travertine.jpg", preset: gallery, camIndex: 1 },
  { id: "editorial-sofa", out: "public/images/editorial/sofa.jpg", preset: gallery, camIndex: 2, mode: "dusk" },
  { id: "editorial-timber", out: "public/images/editorial/timber.jpg", preset: library, camIndex: 1 },
  { id: "editorial-spatial", out: "public/images/editorial/spatial.jpg", preset: pavilion, camIndex: 2 },
  { id: "editorial-trends", out: "public/images/editorial/trends.jpg", preset: suite, camIndex: 0 },
  { id: "editorial-architecture", out: "public/images/editorial/architecture.jpg", preset: court, camIndex: 2 },
];

export const RENDER_BY_ID = Object.fromEntries(RENDERS.map((r) => [r.id, r]));
